def hex_word_sum(input_string):
    def is_valid_hex(word):
        return all(char in '0123456789ABCDEF' for char in word)

    total = 0
    for word in input_string.split():
        word = word.replace('O', '0').replace('S', '5')
        if is_valid_hex(word):
            total += int(word, 16)
    return total
